[
  {
    "text": "Training-free in-context segmentation eliminates the need for retraining and reduces memory overhead compared to class-incremental learning.",
    "topic": "Memory overhead"
  },
  {
    "text": "Shared contextual backgrounds between the reference and query images degrade the performance of existing training-free segmentation methods by elevating similarity in non-target regions.",
    "topic": "Cross-image similarity"
  },
  {
    "text": "REBASE explicitly suppresses spurious contextual correspondences by identifying and projecting the low-rank background feature subspace from the reference image.",
    "topic": "Background subspace elimination"
  },
  {
    "text": "REBASE establishes a new state of the art among training-free methods on PACO-Part, FSS-1000, and cross-domain datasets such as ISIC2018 without any training or parameter updates.",
    "topic": "Performance improvement"
  },
  {
    "text": "Explicit background subspace removal is a highly effective principle for one-shot localization in training-free segmentation.",
    "topic": "Effectiveness of background subspace removal"
  }
]
